tests/lag_alert_test.sh.text:
#!/bin/bash
# STN-41: 遅延の案内の数字は、警告を出す上限（LAG_LIMIT_HOURS）と一致する
fail=0
d=$(mktemp -d); mkdir -p "$d/data/readings"
echo "obs1,2026-11-01T00:00:00Z,10" > "$d/data/readings/latest.csv"
out=$(cd "$d" && NOW=$(date -u -d 2026-11-01T10:00:00Z +%s) bash "$OLDPWD/ops/lag-alert.sh")
echo "$out" | grep -q '最大 6 時間' || { echo "lag message limit: $out"; fail=1; }
echo "$out" | grep -q '24' && { echo "lag message still mentions 24"; fail=1; }
rm -rf "$d"; exit $fail

